// src/routes/sync.ts
var syncRouter = Router2();
syncRouter.post("/batch", requireAuth, csrfProtection, async (req, res) => {
  const studentId = req.session.userId;
  const { attempts } = req.body;
  if (!Array.isArray(attempts) || attempts.length === 0) {
    res.status(400).json({
      error: "Invalid Payload",
      message: 'Batch synchronization payload must contain a non-empty "attempts" array.'
    });
    return;
  }
  const itemizedResults = [];
  let processedCount = 0;
  let acceptedCount = 0;
  let rejectedCount = 0;
  for (const item of attempts) {
    processedCount++;
    if (!item.id || !item.questionId || !item.equation) {
      itemizedResults.push({
        attemptId: item.id || "unknown",
        status: "REJECTED_MALFORMED",
        errorCode: "MISSING_REQUIRED_FIELDS",
        errorMessage: "Attempt payload is missing required question or id fields."
      });
      rejectedCount++;
      continue;
    }
    const canonicalHash = computeCanonicalPayloadHash(
      item.questionId,
      item.equation,
      item.workingSteps,
      item.finalAnswer
    );
    try {
      const existing = await db.select().from(diagnosticAttempts3).where(eq(diagnosticAttempts3.id, item.id)).limit(1);
      if (existing.length > 0) {
        const prev = existing[0];
        if (prev.studentId !== studentId) {
          itemizedResults.push({
            attemptId: item.id,
            status: "REJECTED_CONFLICT",
            errorCode: "ATTEMPT_OWNERSHIP_CONFLICT",
            errorMessage: "Attempt ID is registered to a different account."
          });
          rejectedCount++;
          continue;
        }
        if (prev.payloadHash === canonicalHash) {
          acceptedCount++;
          itemizedResults.push({
            attemptId: item.id,
            status: "ACCEPTED_DUPLICATE",
            validationStatus: prev.validationStatus,
            serverIsCorrect: prev.serverIsCorrect,
            primaryMisconception: prev.serverPrimaryMisconception,
            authoritativeXpAwarded: 0
            // No double XP
          });
          continue;
        } else {
          rejectedCount++;
          itemizedResults.push({
            attemptId: item.id,
            status: "REJECTED_CONFLICT",
            errorCode: "PAYLOAD_HASH_MISMATCH",
            errorMessage: "Attempt ID was previously submitted with a different payload."
          });
          continue;
        }
      }
      const benchmarkQuestion = QUESTION_BANK.find((q) => q.id === item.questionId) || QUESTION_BANK[0];
      const serverDiagnosis = evaluateStudentSubmission(
        benchmarkQuestion,
        item.workingSteps || [],
        item.finalAnswer || ""
      );
      const clientTs = item.clientTimestamp ? new Date(item.clientTimestamp).toISOString() : (/* @__PURE__ */ new Date()).toISOString();
      await db.insert(diagnosticAttempts3).values({
        id: item.id,
        studentId,
        questionId: item.questionId,
        questionVersion: 1,
        engineVersion: "1.2",
        equation: item.equation,
        workingSteps: item.workingSteps || [],
        finalAnswer: item.finalAnswer ? item.finalAnswer.trim() : null,
        payloadHash: canonicalHash,
        serverIsCorrect: serverDiagnosis.isCorrect,
        serverPrimaryMisconception: serverDiagnosis.misconceptionCode,
        validationStatus: "VALIDATED",
        clientTimestamp: clientTs
      });
      if (!serverDiagnosis.isCorrect && serverDiagnosis.misconceptionCode) {
        await db.insert(diagnosticMisconceptions3).values({
          id: generateUUID(),
          attemptId: item.id,
          misconceptionCode: serverDiagnosis.misconceptionCode,
          confidenceScore: 100,
          supportingEvidence: {
            faultyStepNumber: serverDiagnosis.faultyStepNumber,
            faultyExpression: serverDiagnosis.faultyExpression,
            expectedExpression: serverDiagnosis.expectedExpression
          }
        });
      }
      let earnedXp = 0;
      const tx1Id = generateUUID();
      const reward1 = await db.insert(rewardTransactions3).values({
        id: tx1Id,
        studentId,
        activityType: "diagnostic_complete",
        referenceId: item.id,
        pointsAwarded: 10,
        description: `Completed diagnostic problem: ${item.equation}`
      }).onConflictDoNothing().returning();
      if (reward1.length > 0) earnedXp += 10;
      const stepCount = (item.workingSteps || []).filter(
        (s2) => s2.mathExpression && s2.mathExpression.trim().length > 0
      ).length;
      if (stepCount >= 2) {
        const tx2Id = generateUUID();
        const reward2 = await db.insert(rewardTransactions3).values({
          id: tx2Id,
          studentId,
          activityType: "working_steps_provided",
          referenceId: `${item.id}_steps`,
          pointsAwarded: 5,
          description: "Provided complete intermediate working steps"
        }).onConflictDoNothing().returning();
        if (reward2.length > 0) earnedXp += 5;
      }
      acceptedCount++;
      itemizedResults.push({
        attemptId: item.id,
        status: "ACCEPTED",
        validationStatus: "VALIDATED",
        serverIsCorrect: serverDiagnosis.isCorrect,
        primaryMisconception: serverDiagnosis.misconceptionCode,
        authoritativeXpAwarded: earnedXp
      });
    } catch (err) {
      console.error(`Error processing attempt ${item.id}:`, err);
      rejectedCount++;
      itemizedResults.push({
        attemptId: item.id,
        status: "REJECTED_SERVER_ERROR",
        errorCode: "TRANSACTION_FAILED",
        errorMessage: "Database transaction error processing attempt."
      });
    }
  }
  try {
    const xpQuery = await db.select({ totalXp: sql`COALESCE(SUM(${rewardTransactions3.pointsAwarded}), 0)` }).from(rewardTransactions3).where(eq(rewardTransactions3.studentId, studentId));
    const totalXp = Number(xpQuery[0]?.totalXp || 0);
    const recentAttempts = await db.select({ isCorrect: diagnosticAttempts3.serverIsCorrect }).from(diagnosticAttempts3).where(and(eq(diagnosticAttempts3.studentId, studentId), eq(diagnosticAttempts3.validationStatus, "VALIDATED"))).limit(20);
    let masteryPercentage = null;
    if (recentAttempts.length > 0) {
      const correctCount = recentAttempts.filter((a) => a.isCorrect === true || a.isCorrect === 1).length;
      masteryPercentage = Math.round(correctCount / recentAttempts.length * 100);
    }
    await db.update(studentProfiles3).set({
      totalXp,
      masteryPercentage,
      updatedAt: (/* @__PURE__ */ new Date()).toISOString()
    }).where(eq(studentProfiles3.id, studentId));
    const updatedProfiles = await db.select().from(studentProfiles3).where(eq(studentProfiles3.id, studentId)).limit(1);
    res.json({
      success: true,
      processedCount,
      acceptedCount,
      rejectedCount,
      itemizedResults,
      authoritativeProfile: updatedProfiles[0] || null,
      serverTimestamp: (/* @__PURE__ */ new Date()).toISOString()
    });
  } catch (err) {
    console.error("Error computing authoritative profile aggregates:", err);
    res.json({
      success: true,
      processedCount,
      acceptedCount,
      rejectedCount,
      itemizedResults,
      serverTimestamp: (/* @__PURE__ */ new Date()).toISOString()
    });
  }
});

