import { Router as Router7 } from "express";
var studentRouter = Router7();
studentRouter.post("/classrooms/join", requireAuth, requireRole("student"), async (req, res) => {
  try {
    const studentUserId = req.session.userId;
    const { inviteCode } = req.body;
    if (!inviteCode || typeof inviteCode !== "string") {
      res.status(400).json({ error: "Bad Request", message: "Invite code is required." });
      return;
    }
    const cleanCode = inviteCode.trim().toUpperCase();
    const studentProfs = await db.select().from(studentProfiles3).where(eq(studentProfiles3.id, studentUserId)).limit(1);
    if (studentProfs.length === 0) {
      res.status(404).json({ error: "Not Found", message: "Student profile record not found." });
      return;
    }
    const foundClasses = await db.select().from(classrooms3).where(eq(classrooms3.inviteCode, cleanCode)).limit(1);
    if (foundClasses.length === 0) {
      res.status(404).json({ error: "Not Found", message: "Invalid or expired classroom invite code." });
      return;
    }
    const targetClass = foundClasses[0];
    if (targetClass.status === "archived") {
      res.status(400).json({ error: "Forbidden", message: "This classroom is archived and no longer accepting enrollments." });
      return;
    }
    const existingMembership = await db.select().from(classroomMemberships3).where(
      and(
        eq(classroomMemberships3.classroomId, targetClass.id),
        eq(classroomMemberships3.studentId, studentUserId)
      )
    ).limit(1);
    if (existingMembership.length > 0) {
      await db.update(classroomMemberships3).set({ status: "active" }).where(eq(classroomMemberships3.id, existingMembership[0].id));
    } else {
      await db.insert(classroomMemberships3).values({
        id: generateUUID(),
        classroomId: targetClass.id,
        studentId: studentUserId,
        status: "active"
      });
    }
    const teacherInfo = await db.select({ fullName: teacherProfiles3.fullName, schoolName: teacherProfiles3.schoolName }).from(teacherProfiles3).where(eq(teacherProfiles3.id, targetClass.teacherId)).limit(1);
    res.json({
      success: true,
      classroom: {
        ...targetClass,
        teacher: teacherInfo[0] || { fullName: "Teacher", schoolName: "" }
      }
    });
  } catch (err) {
    console.error("Error in POST /api/student/classrooms/join:", err);
    res.status(500).json({ error: "Server Error", message: "Failed to join classroom." });
  }
});
studentRouter.get("/classrooms", requireAuth, requireRole("student"), async (req, res) => {
  try {
    const studentUserId = req.session.userId;
    const memberships = await db.select({
      classroomId: classroomMemberships3.classroomId,
      joinedAt: classroomMemberships3.joinedAt
    }).from(classroomMemberships3).where(
      and(
        eq(classroomMemberships3.studentId, studentUserId),
        eq(classroomMemberships3.status, "active")
      )
    );
    if (memberships.length === 0) {
      res.json({ classrooms: [] });
      return;
    }
    const classIds = memberships.map((m2) => m2.classroomId);
    const enrolledClasses = await db.select().from(classrooms3).where(sql`${classrooms3.id} IN (${sql.join(classIds.map((id2) => sql`${id2}`), sql`, `)})`);
    const classroomsWithTeacher = await Promise.all(
      enrolledClasses.map(async (cls) => {
        const teacher = await db.select({ fullName: teacherProfiles3.fullName, schoolName: teacherProfiles3.schoolName }).from(teacherProfiles3).where(eq(teacherProfiles3.id, cls.teacherId)).limit(1);
        return {
          ...cls,
          teacher: teacher[0] || { fullName: "Teacher", schoolName: "" }
        };
      })
    );
    res.json({ classrooms: classroomsWithTeacher });
  } catch (err) {
    console.error("Error in GET /api/student/classrooms:", err);
    res.status(500).json({ error: "Server Error", message: "Failed to retrieve enrolled classrooms." });
  }
});
